 if(k==='compose'){t.bins=['Claim','Evidence','Reasoning / limitation'];t.cards=[{label:b.apply.answer,bin:0},{label:b.source.slice(0,220),bin:1},{label:b.reason.slice(0,220),bin:2}];t.brief='Build an evidence-based explanation. Put the conclusion in Claim, observations in Evidence, and the connection or caution in Reasoning. Read the finished argument aloud and defend it.';}
