 if(k==='deduce'){t.suspects=(GP_DEDUCTIONS[i]||GP_DEDUCTIONS[0]).map(([label,...facts])=>({label,facts}));t.target=v%t.suspects.length;t.questions=['Reveal location / form clue','Reveal surface / setting clue','Reveal process / connection clue'];t.brief='Investigate the mystery landscape. Ask at least two geographical questions. Compare the clues with the candidate records and eliminate every inconsistent candidate. Explain why your surviving candidate fits all clues.';}
 if(k==='layers'){Object.assign(t,{layers:[{label:'Flood / fragile ground',cells:[12,13,14,15,16,17]},{label:'Service access',cells:[1,2,3,7,8,9,19,20,21]},{label:'Protected land',cells:[1,7,19,20]}],valid:[2,3,8,9,21],rule:'Inspect all three layers. Choose a site with service access (2), outside hazard (1) and protected land (3).'});t.brief='Planning desk for '+GEO_PLAN[i].topic+'. This fictional local grid tests how overlapping layers change a decision. Toggle each layer, compare constraints, then place one approved site. '+t.rule;}
 if(k==='survey'){Object.assign(t,{values:Array.from({length:30},(_,n)=>1+(n*7+i+v)%9),zones:Array.from({length:30},(_,n)=>n%3),samples:6});t.brief='Run a stratified field sample for '+GEO_PLAN[i].topic+'. This fictional grid contains model observations, not actual case-study measurements. Take two readings from each of zones A, B and C. Report the sum of your six readings. Explain why sampling only one zone could mislead.';}
 if(k==='sculpt'){const deposit=i===29;Object.assign(t,{rock:Array(24).fill(deposit?0:3),target:Array.from({length:24},(_,n)=>deposit?(n%6===0||n%6===5?2:0):[3,2,1,1,2,3][n%6]),process:deposit?'Build lateral moraine ridges along both edges':'Widen and deepen a simplified valley cross-section'});t.brief=(deposit?'Deposit debris along the glacier sides.':'Erode the centre more deeply than the sides to form a broad trough.')+' Each of the four rows represents a repeated cross-section. Target heights left to right: '+t.target.slice(0,6).join(', ')+'. This block model simplifies the landscape; it does not represent real rock strength.';if(i===35||i===36){t.target=Array.from({length:24},(_,n)=>[3,2,0,1,2,3][n%6]);t.process='Carve an asymmetric river channel';t.brief='Model a river bend cross-section. Erode the outer-bank side deeply, leaving a shallower inner side. Set each row to heights 3, 2, 0, 1, 2, 3 from left to right. This is a simplified cross-section, not a plan view of a meander.';}}
 if(k==='sort'&&t.bins[0]!=='Supported by evidence')t.brief='Sort every field card into '+t.bins.join(', ')+'. Select or drag a card to its category. Tap an assigned card to return it to the collection. Explain what distinguishes the categories.';
